use gtkg_core::{CallContext,Dispatcher,EffectPolicy,TransportKind};
use gtkg_protocol::{FileReceiptRef,v2::{OperationRequestV2,PROTOCOL_VERSION_V2},v04::ArtifactPayload};
use serde_json::{Value,json};
use std::{fs,io::Write,path::Path,process::{Command,Stdio}};
fn git(r:&Path,a:&[&str])->String{let x=Command::new("git").arg("-C").arg(r).args(a).output().expect("git");assert!(x.status.success());String::from_utf8(x.stdout).expect("text").trim().into()}
fn setup()->(tempfile::TempDir,CallContext,FileReceiptRef){let t=tempfile::tempdir().expect("temp");let r=t.path().join("repo");let w=t.path().join("work");fs::create_dir(&r).expect("repo");fs::create_dir(&w).expect("work");git(&r,&["init","-q"]);let files=[("main.go","package main\nfunc helper() {}\nfunc main(){ helper(); helper() }\n"),("README.md","# Recovery\nSession recovery returns new_session_required for a nonempty session.\n")];let mut b=Vec::new();for(i,(_,s))in files.iter().enumerate(){b.extend(format!("blob\nmark :{}\ndata {}\n{}\n",i+1,s.len(),s).as_bytes())}b.extend(b"commit refs/heads/main\ncommitter Fixture <fixture@example.invalid> 0 +0000\ndata 3\nqk\n\n");for(i,(p,_))in files.iter().enumerate(){b.extend(format!("M 100644 :{} {}\n",i+1,p).as_bytes())}b.push(b'\n');let mut p=Command::new("git").arg("-C").arg(&r).args(["fast-import","--quiet"]).stdin(Stdio::piped()).spawn().expect("import");p.stdin.take().expect("stdin").write_all(&b).expect("write");assert!(p.wait().expect("wait").success());let c=CallContext::restricted(TransportKind::Test,vec![w.clone(),r.clone()],EffectPolicy::WorkspaceWrite).expect("ctx");let v=call(&c,"source.capture",json!({"repository_id":"fixture","source_root":r,"source_commit":git(&r,&["rev-parse","main"]),"expected_tree":git(&r,&["rev-parse","main^{tree}"]),"output_path":w.join("archive"),"policy":{"revision":"all/v1","rules":[],"archive_binary":false}}));let p=call(&c,"analysis.plan",json!({"workspace_root":w,"artifact_ref":v["artifact_ref"]}));(t,c,serde_json::from_value(p["artifact_ref"].clone()).expect("ref"))}
fn call(c:&CallContext,op:&str,mut p:Value)->Value{p["payload_revision"]=json!("gtkg.knowledge-quality/v0.4-r1");Dispatcher.execute_v2(c,OperationRequestV2{protocol_version:PROTOCOL_VERSION_V2.into(),operation_id:op.into(),request_id:"qk-analysis".into(),payload:p}).expect(op).result}

use gtkg_core::v04::{authoring::*,knowledge::*,artifact};
use gtkg_extract::v04::Span;
use std::collections::BTreeMap;
#[test]fn typed_authoring_chain_writes_only_replayed_accepted_okf(){
 let(t,c,plan)=setup();let w=t.path().join("work");
 let build=call(&c,"analysis.build",json!({"workspace_root":w,"artifact_ref":plan}));let verified=call(&c,"analysis.verify",json!({"workspace_root":w,"artifact_ref":build["artifact_ref"]}));
 let input=JobRequest{verified_ref:serde_json::from_value(verified["artifact_ref"].clone()).unwrap(),input:KnowledgeInput{job_id:"fixture-entry".into(),goal:KnowledgeGoal::SemanticUnderstanding,source_paths:vec!["main.go".into()],understanding_items:vec!["entry".into()],prompt:"Explain definitions using exact evidence".into(),policy:"fixture-only".into(),max_context_units:8000,source_spans:BTreeMap::new()}};
 let r=artifact::publish(&c,&w,"inputs",&input).unwrap();let job=call(&c,"summary.job.next",json!({"workspace_root":w,"artifact_ref":r}));let job_ref=artifact::publish(&c,&w,"inputs",&job["job_artifact"]).unwrap();let(j,_):(JobArtifact,_)=artifact::read(&c,&w,&job_ref).unwrap();
 let raw="package main\nfunc helper() {}\nfunc main(){ helper(); helper() }\n";
 let candidate=KnowledgeCandidate{author_id:"fixture-author".into(),author_mode:AuthorMode::HumanAuthored,summary:"Fixture declarations".into(),claims:vec![KnowledgeClaim{claim_id:"entry".into(),understanding_item:"entry".into(),natural_language:"helper is declared".into(),body:ClaimBody::Structural{predicate:Predicate::Declares{path:"main.go".into(),name:"helper".into(),kind:"function".into()},polarity:true},citations:vec![Citation{path:"main.go".into(),file_sha256:digest(raw.as_bytes()),span:Span{byte_start:13,byte_end:30,line_start:2,line_end:2},excerpt:"func helper() {}\n".into()}]}]};
 let output=serde_json::to_string(&candidate).unwrap();let record=GenerationExecutionRecord{schema:"gtkg.qk.generation-execution-record/v1".into(),job_digest:j.job.job_digest.clone(),context_digest:j.job.context_digest.clone(),prompt_digest:j.job.prompt_digest.clone(),policy_digest:j.job.policy_digest.clone(),author_id:candidate.author_id.clone(),author_mode:candidate.author_mode.clone(),execution_evidence:ExecutionEvidence::HumanRecorded,host_id:None,model_id:None,transcript:None,transcript_digest:None,output_digest:digest(output.as_bytes()),output,usage:Usage{input_tokens:None,output_tokens:None}};
 let input=ProposalRequest{job_ref,candidate,execution_record:Some(record)};let r=artifact::publish(&c,&w,"inputs",&input).unwrap();let proposal=call(&c,"summary.proposal.submit",json!({"workspace_root":w,"artifact_ref":r}));let proposal_ref=serde_json::from_value(proposal["artifact_ref"].clone()).unwrap();let(p,_):(ProposalArtifact,_)=artifact::read(&c,&w,&proposal_ref).unwrap();
 let reviews=["reviewer-a","reviewer-b"].iter().map(|id|IndependentReview{reviewer_id:id.to_string(),proposal_digest:p.proposal.proposal_digest.clone(),decisions:p.proposal.candidate.claims.iter().map(|cl|ClaimReview{claim_id:cl.claim_id.clone(),claim_digest:claim_digest(cl).unwrap(),judgment:Judgment::Supported,reason:"Fixture source oracle".into()}).collect()}).collect();
 let r=artifact::publish(&c,&w,"inputs",&ReviewRequest{proposal_ref,reviews}).unwrap();let v=call(&c,"summary.verification.submit",json!({"workspace_root":w,"artifact_ref":r}));let accepted=call(&c,"summary.accept.v2",json!({"workspace_root":w,"artifact_ref":v["artifact_ref"]}));assert_eq!(accepted["knowledge_ready"],true);assert_eq!(accepted["llm_qa_validated"],false);let reference:FileReceiptRef=serde_json::from_value(accepted["okf_ref"].clone()).unwrap();let bytes=fs::read(w.join(reference.path)).unwrap();let text=String::from_utf8(bytes).unwrap();assert!(text.starts_with("---\n"));assert!(text.contains("main.go"));assert!(text.contains("helper"));assert!(!text.contains("GPT"));
}
